style.css:
/* Insta Midnight — Instagram */

/* colors — swap these values if you like */
:root {
  --my-bg: #101014;
  --my-card: #191820;
  --my-accent: #a855f7;
  --my-text: #f5f3ff;
  --my-muted: #a19bad;
}

/* dark background */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* typography */
body {
  font-family: "Segoe UI", Arial, sans-serif !important;
}

/* links */
a {
  color: #c084fc !important;
}

/* images */
img {
  border-radius: 8px;
}

/* selection */
::selection {
  background: var(--my-accent) !important;
  color: white !important;
}

/* smooth scrolling */
html {
  scroll-behavior: smooth !important;
}
